// Normaliza o evento recebido do Whaticket (Baileys ou camada WAHA) e controla pausa por chat
const raw = $input.first().json.body || $input.first().json;
const sd = $getWorkflowStaticData('global');
sd.pausados = sd.pausados || {};
const cfg = raw._integrationConfig || {};
const p = raw.payload || {};
const out = (o) => [{ json: Object.assign({ responder: false, pausado: false, ticketId: cfg.ticketId || p.ticketId || null, integrationId: cfg.integrationId || null }, o) }];

// Suporte a formato nativo Baileys (Whaticket) caso payload WAHA não esteja presente
const remoteJid = (raw.key && raw.key.remoteJid) || p.from || '';
const fromMe = Boolean((raw.key && raw.key.fromMe) ?? p.fromMe);
const ev = raw.event || (raw.key ? 'message' : '');

if (ev === 'call.received') {
  const chatId = p.from || remoteJid;
  if (!chatId || String(chatId).includes('@g.us')) return out({});
  return out({ responder: true, pausado: !!sd.pausados[chatId], chatId, tipo: 'audio', text: '' });
}

if (ev !== 'message' && ev !== 'message.any') return out({});
if (String(remoteJid).includes('@g.us') || String(p.to || '').includes('@g.us')) return out({});
if (String(remoteJid).includes('status@broadcast')) return out({});

const baileysMsg = raw.message || {};
const rawBody = p.body || baileysMsg.conversation || (baileysMsg.extendedTextMessage && baileysMsg.extendedTextMessage.text) || (baileysMsg.imageMessage && baileysMsg.imageMessage.caption) || (baileysMsg.documentMessage && baileysMsg.documentMessage.caption) || '';

// Mensagem enviada pela equipe: comando "#bot" reativa o robô
if (fromMe) {
  const chat = ( p.to && p.to !== 'me@c.us' ? p.to : remoteJid ).replace('@s.whatsapp.net', '@c.us');
  const t = String(rawBody).trim().toLowerCase();
  if (t === '#bot' && chat) delete sd.pausados[chat];
  if (t === '#pausar' && chat) sd.pausados[chat] = Date.now();
  return out({});
}

const chatId = String(p.from || remoteJid).replace('@s.whatsapp.net', '@c.us');
const mime = String((p.media && p.media.mimetype) || (p._data && p._data.mimetype) || (baileysMsg.audioMessage && baileysMsg.audioMessage.mimetype) || '');
const tp = String((p._data && p._data.type) || p.type || (baileysMsg.audioMessage ? 'ptt' : ''));
const ehAudio = mime.startsWith('audio') || tp === 'ptt' || tp === 'audio' || Boolean(baileysMsg.audioMessage);
const bodyTxt = String(rawBody).trim();
const hasMedia = Boolean(p.hasMedia || baileysMsg.imageMessage || baileysMsg.documentMessage || baileysMsg.videoMessage);

let tipo = 'texto';
let text = bodyTxt;
if (ehAudio) { tipo = 'audio'; text = ''; }
else if (hasMedia) {
  tipo = 'arquivo';
  const nome = (p.media && p.media.filename) || (p._data && p._data.filename) || (baileysMsg.documentMessage && baileysMsg.documentMessage.fileName) || mime || 'arquivo';
  text = '[Cliente enviou um arquivo/imagem: ' + nome + ']' + (bodyTxt ? ' Legenda: ' + bodyTxt : '');
}
if (!text && tipo !== 'audio') return out({});

return out({ responder: true, pausado: !!sd.pausados[chatId], chatId, tipo, text });

// Detecta o transbordo, pausa o bot para o chat e limpa a resposta
const sd = $getWorkflowStaticData('global');
sd.pausados = sd.pausados || {};
const prep = $('Filtrar e Preparar').first().json;
const chatId = prep.chatId;
const ticketId = prep.ticketId || null;
const integrationId = prep.integrationId || null;
let texto = String($json.output || $json.text || '').trim();
const transbordo = texto.includes('<AGUARDANDO_HUMANO>');
texto = texto.replace(/<AGUARDANDO_HUMANO>/g, '').replace(/\*\*/g, '*').trim();
if (transbordo) sd.pausados[chatId] = Date.now();
return [{ json: { chatId, texto, transbordo, ticketId, integrationId } }];
